/**
 * Language-bound data: heuristics that read note text, and headings dummkopf generates.
 *
 * CLI messages stay in messages.ts (English). This module only changes what dummkopf reads out of
 * notes and what it writes into generated files, so an existing brain in another language keeps its
 * INDEX.md and README tables byte-identical.
 */

import { BOUNDARY as B, ignoreCase, WS } from "./py.ts";

export interface Locale {
  readonly stopwords: ReadonlySet<string>;
  readonly thisWeek: RegExp;
  readonly nextWeek: RegExp;
  readonly negations: ReadonlySet<string>;
  readonly without: ReadonlySet<string>;
  /** Groups `year` (optional), `month`, `day`. Digits are any Unicode decimal digits, like Python's `\\d`. */
  readonly rowDate: RegExp;
  readonly periodConnector: string;
  readonly months: Readonly<Record<string, number>>;
  readonly dayMonthYear: RegExp | null;
  readonly openWords: readonly string[];
  readonly updatedLabel: RegExp;
  readonly dateFormats: readonly string[];
  readonly archiveHint: string;
  readonly filesHeading: string;
  readonly stubHeading: string;
  readonly indexTopics: string;
  readonly indexNotes: string;
  readonly indexBookmarks: string;
  readonly topicColumns: readonly [string, string, string];
  readonly fileColumns: readonly [string, string, string];
  readonly linksGenerated: string;
  readonly linksTime: string;
  readonly linksEntities: string;
  readonly linksCollisions: string;
  readonly linksNone: string;
  readonly linksTopics: string;
  readonly linksExcluded: string;
}

function wordSet(text: string): ReadonlySet<string> {
  return new Set(text.split(" "));
}

export const EN: Locale = {
  stopwords: wordSet(
    "what how why when where who which whose is are was were does do did there has have had "
    + "the a an i you we me my our must should can could would for with from to in on at of by "
    + "about after and or it please show tell give me us all anything something still already",
  ),
  thisWeek: new RegExp(B + "this week" + B, "u"),
  nextWeek: new RegExp(B + "next week" + B, "u"),
  negations: wordSet("not no none never"),
  without: wordSet("without except excluding"),
  rowDate: new RegExp(B + "(?:(?<year>\\p{Nd}{4})-)?(?<month>\\p{Nd}{1,2})-(?<day>\\p{Nd}{1,2})" + B, "u"),
  periodConnector: "to",
  months: {
    january: 1, jan: 1, february: 2, feb: 2, march: 3, mar: 3, april: 4, apr: 4,
    may: 5, june: 6, jun: 6, july: 7, jul: 7, august: 8, aug: 8,
    september: 9, sept: 9, sep: 9, october: 10, oct: 10, november: 11, nov: 11,
    december: 12, dec: 12,
  },
  dayMonthYear: null,
  openWords: ["open question", "to check", "unverified", "TODO", "TBD", "not yet"],
  updatedLabel: new RegExp("(?:" + ignoreCase("As of") + "|" + ignoreCase("Updated") + "):?" + WS + "*(\\p{Nd}{4}-\\p{Nd}{2}-\\p{Nd}{2})", "u"),
  dateFormats: ["%Y-%m-%d"],
  archiveHint: "archive",
  filesHeading: "## Files",
  stubHeading: "## Unfiled (auto-stub)",
  indexTopics: "## Topics",
  indexNotes: "## Notes (flat)",
  indexBookmarks: "## Bookmarks",
  topicColumns: ["Folder", "About", "Aliases"],
  fileColumns: ["File", "Key fact", "Aliases"],
  linksGenerated: "Generated by dummkopf on {date}. Do not edit by hand.",
  linksTime: "## Time links",
  linksEntities: "## Entity links",
  linksCollisions: "## Collisions",
  linksNone: "None found.",
  linksTopics: "Topics",
  linksExcluded: "{files} sensitive files and {topics} sensitive topics excluded.",
};

// German stopwords are ASCII-folded because the search folds umlauts before matching.
